      "動物実験に関する国際的な指針として3Rの原則（代替・削減・改善）が広く採用されており、日本の動物愛護管理法もこれを基本方針に取り入れている",
      "工場畜産における密閉環境での飼育は動物に持続的なストレスと苦痛をもたらすとされ、功利主義的観点から批判の対象となることが多い",
      "功利主義は行為功利主義と規則功利主義に分かれ、前者は個別行為の結果を、後者は従うべきルール全体がもたらす結果を評価基準とするため、動物利用の許容範囲について異なる結論が導かれうる",
      "J.S.ミルは快楽に質的差異を認め、高次の知的快楽と低次の肉体的快楽を区別したが、この区別を動物の苦痛評価に適用すると論争的な結論が生じる",
