    suggestedStructure: "まず功利主義の核心原理（快苦の総量による評価）を簡潔に定義し、動物が苦痛を感じる存在である事実を踏まえてその利益を計算に含める根拠を示す。次に食用・実験それぞれについて人間の利益と動物の苦痛を比較衡量し、苦痛最小化の条件付きで容認されうるのか全面的に問題があるのかを論じたうえで、功利主義的観点からどのような制度・代替手段が求められるかを示して結論とする。",
