      "デジタル庁の2023年度調査では行政手続きのオンライン化率が目標の100パーセントに対し約6割にとどまり、デジタル行政の遅れが指摘されている",
      "厚生労働省の2022年国民生活基礎調査によれば子どもの貧困率は11.5パーセントであり、ひとり親世帯では44.5パーセントと依然として高水準にある",
      "気候変動に関する政府間パネル（IPCC）第6次評価報告書（2023年）は、現行の削減目標では産業革命前比1.5度抑制が達成困難であると警告している",
