      "日本では生活保護の捕捉率が推計で2割程度とされており、制度が存在しながら本来受給できるはずの困窮者の多くが申請に至っていないという逆説的な状況がある",
      "ヤングケアラー問題に関して、国の実態調査では中学2年生の約5パーセント前後が家族の世話をしていると回答しており、教育機会の喪失という不条理な連鎖が社会問題化している",
      "外国にルーツを持つ子どもの就学機会については、義務教育の対象外となる場合があり、言語支援の不足と相まって教育格差が生じている実態が指摘されている",
