    argumentAngles: [
      "個人の努力や選択の問題として捉える視点と、構造・制度・歴史的経緯によって生まれた問題として捉える視点を対比させることで、不条理の根源をより深く定義できる",
      "短期的な対症療法的解決策と、制度設計や規範変容を促す長期的な根本解決策という二軸で解決策を評価することで論の深みを出せる",
      "市場原理や効率性の論理が生む帰結と、公正・公平・人間の尊厳を優先する倫理的論理とを対立させることで不条理の構造的矛盾を浮き彫りにできる",
      "当事者視点からの問題定義と、政策立案者や社会全体からの俯瞰的視点を組み合わせることで、問題の多面性を示しつつ説得力のある解決策を提示できる",
      "テクノロジーやデータ活用による解決可能性と、制度改革や意識変革が必要な側面とを分けて論じることで、SFC的な問題解決思考を発揮できる",
    ],
    suggestedStructure: "序論で具体的な不条理現象を一つ明示し問題を定義する、本論前半でその構造的原因を多角的に分析し本論後半で実現可能性を意識した複数の解決策を提案する、結論でその解決策が社会に与えるより広い意義や残る課題に触れて締める構成が論理の流れとして自然である。",
