      "文部科学省の調査によると日本語指導が必要な外国籍の児童生徒数は2022年度時点で約5万8千人に上り、指導体制の不足が各地で課題となっている",
      "法務省の調査では外国人住民が日常生活で困ること・差別を感じる場面として、住居確保の困難や職場・地域での偏見・言語的排除が上位に挙げられている",
      "ヘイトスピーチ解消法は2016年に施行されたが罰則規定を持たない理念法であり、差別的言動の抑止に向けた実効性の限界が継続的に議論されている",
