      "日本の外国語教育政策では2020年度から小学校3年生以上で英語教育が段階的に導入され、グローバル人材育成が国家戦略として位置づけられている一方、母語教育や多言語教育の後退を懸念する声もある。",
      "文化的多様性の保護を目的とするユネスコの「文化的表現の多様性の保護及び促進に関する条約」は2005年に採択され、言語・文化の均質化に対抗する国際的な制度的枠組みとなっている。",
