      "罰則付き刑事規制・行政的公表制度・理念法による啓発という規制手法の強度の違いを検討し、日本の現行制度の実効性と立法論的課題を考察する視点。",
      "表現規制が特定の政治的意見や少数意見の抑圧に転用されるリスク（濫用の危険性）と、規制なき放置が被害を受けるマイノリティの表現・参加の機会を実質的に奪うという逆説的萎縮効果をめぐる緊張関係。",
      "国際人権法上の義務（自由権規約20条等）と国内憲法上の表現の自由保障の調整問題、すなわち国際標準への整合性という観点から日本の立法不作為を問う視点。",
