    suggestedStructure: "序論で表現の自由とヘイトスピーチ規制が対立する構造的理由と問いを提示し、本論前半でアメリカ・ドイツ・日本の規制モデルを比較しながら各国のアプローチが依拠する価値原理を析出し、本論後半でいかなる基準・範囲・手法による規制が表現の自由との両立可能性を持つかを論じ、結論で日本が採るべき方向性について自らの見解を示す。",
