      "薬剤の色とプラセボ効果の関係については古くから研究があり、赤・橙色の錠剤は興奮・鎮痛作用が高く知覚されやすく、青・緑色の錠剤は鎮静・睡眠補助として期待されやすい傾向が報告されている",
      "医療施設の壁面色や照明色を変更した介入研究では、落ち着いた緑系・青系の環境色が患者の不安スコアや疼痛評価スコアを低下させる方向に作用したとする報告が複数存在する",
      "光線療法（光療法）は季節性感情障害（SAD）の標準的治療法として位置づけられており、高照度白色光（2500〜10000ルクス）の朝の照射がセロトニン系を活性化し抑うつ症状を改善することが臨床的に確認されている",
