      "OECDの報告によれば、自動化リスクの低い職種の共通スキルとして批判的思考・コミュニケーション・倫理判断が挙げられており、人文系教育との親和性が指摘されている",
      "東京大学が実施した学生調査では、文学部卒業生の進路は教育・出版・官公庁・民間企業と多岐にわたり、特定職種への直結よりも汎用的思考力の習得が評価されている傾向がある",
      "人文学・社会科学分野の研究は定量的成果指標（論文引用数・特許件数など）になじみにくく、研究評価指標の設計そのものが学問の性格と齟齬をきたすというジレンマが国際的に議論されている",
      "ChatGPTをはじめとする生成AIの普及により、文章生成・情報要約が自動化される一方、テクストの批判的読解・解釈・文脈理解はむしろ人間的能力の固有領域として注目が高まっている",
