      "科学的不確実性と意思決定のタイムラインのジレンマ：感染症対策では完全な証拠が揃う前に政策判断が求められるため、科学者がどの段階でどの程度の確信を持って発言すべきかという問いが生じる",
      "科学技術の両義性に対して、規制・倫理審査・国際条約による「外部的制御」に委ねるべきか、科学者コミュニティ内部の自律的規範に頼るべきかという統治構造の問い",
      "グローバルな感染症対策における先進国と途上国の非対称性：ワクチン特許・技術移転・サーベイランス能力の格差は、科学の成果が平等に恩恵をもたらすわけではないことを示し、科学者の責任の範囲を国境を超えて考える視点を提供する",
      "科学コミュニケーションの問題：科学者が正確な情報を発信しても、社会的文脈・政治的フィルター・メディアの解釈によって歪められる場合があり、科学者にはその歪みへの対処責任があるかという論点",
