      "IMFの研究（2014年以降複数）は、過度な格差は中長期的な経済成長率を低下させるという実証結果を示しており、成長と公平は必ずしもトレードオフではないとする見解が有力になっている",
      "日本の国民負担率は2023年度で約46%前後に達しており、社会保障費の増大が財政制約の中で再分配政策の拡充を困難にしている側面がある",
