    argumentAngles: [
      "参加の拡大と質の問題という対立軸：デジタル技術は地理的・時間的障壁を下げて政治参加の裾野を広げるが、熟議なき参加や感情的動員が民主的意思決定の質を低下させるリスクがあるという視点",
      "情報の民主化と情報操作という対立軸：デジタル技術は権力が独占してきた情報を市民に開放する力を持つが、同時にフェイクニュースやディープフェイクによる世論操作を容易にするという二面性の視点",
      "国家主権とプラットフォーム権力という視点：グーグルやメタなどの民間プラットフォーム企業が事実上の「言論空間の統治者」となっており、民主的コントロールの外に置かれた私的権力が民主主義制度に与える構造的影響を問う視点",
      "グローバルな比較という視点：台湾・エストニアのようにデジタル民主主義を積極的に推進する国と、中国のように国家がデジタル技術を権威主義的統治に活用する国を対比させ、技術の政治的中立性を問う視点",
      "デジタルデバイドと民主的平等という視点：アクセス格差・リテラシー格差がデジタル化された政治参加において特定層を排除する構造を生み出し、民主主義の根本原理である平等性を損なう可能性という視点",
    ],
    suggestedStructure: "序論でデジタル民主主義の定義と問いの所在（技術は民主主義を強化するか弱体化させるか）を示し、本論前半で市民参加の拡大や情報公開というメリットを具体例とともに論じ、本論後半でフェイクニュース・プラットフォーム権力・デジタルデバイドというリスクを構造的に分析し、結論では両面を踏まえた上で民主主義の質を守るために必要な制度的・社会的条件（法規制・メディアリテラシー教育等）を自分の立場から提示する。",
