      "2023年のノルウェー・ハーバード大学などの研究では、Facebookのアルゴリズム変更実験を通じて、フィード表示がユーザーの政治的極化に一定程度寄与することが示された",
      "国内の内閣府調査では、SNSを介したいじめや誹謗中傷の相談件数が近年増加傾向にあり、特に10代の被害が目立つと報告されている",
      "一方でSNSは2024年能登半島地震をはじめとする災害時の安否確認・情報共有ツールとして行政・市民双方に活用された実績がある",
      "WHO等の報告では、SNSの過剰利用と若者のメンタルヘルス悪化（孤独感・抑うつ傾向）との相関を示す研究が蓄積されつつあるが、因果関係の証明は現在も議論中である",
