      "厚生労働省の調査によれば定期的な運動・スポーツ習慣を持つ成人は全体の3割程度にとどまっており、身体活動不足はすでに生活習慣病リスクの主因の一つとされているが、スポーツという文化的枠組みの消滅はさらなる不活動社会を招きうる",
      "オリンピック・パラリンピックはIOC憲章においてスポーツを通じた平和と人間の尊厳の尊重を理念とし、200以上の国と地域が参加する最大規模の国際イベントであり、その消滅は国家間の平和的競争の場の喪失を意味する",
      "スポーツ観戦・参加はメンタルヘルス改善や社会的孤立の解消に寄与するという研究知見が蓄積されており、孤独・孤立対策が国家課題となっている日本においてコミュニティ形成機能の消滅は深刻な社会問題につながりうる",
      "学校体育はスポーツの制度的基盤であり、身体能力の育成だけでなく規範意識・協調性・レジリエンスなど非認知能力の涵養に関わるとされており、その消滅は教育課程全体の再設計を迫る問題となる",
