      "経済・産業の視点：スポーツ関連産業の消滅による雇用や観光への打撃という負の側面と、その資源が他産業に再配分されうるという楽観論の対立",
      "社会統合・コミュニティの視点：スポーツが担う地域や国民の一体感・連帯感の喪失という議論と、スポーツ以外の文化的活動でも同様の機能が果たせるかという問い",
      "教育・人間形成の視点：競争・協働・敗北からの回復といったスポーツ固有の経験が失われることで人格形成や非認知能力の育成にどう影響するかという教育学的問い",
      "平和・外交・アイデンティティの視点：スポーツが国家間の緊張緩和や文化交流に果たしてきた役割の喪失を問う一方で、スポーツがナショナリズムや商業主義と結びついてきた負の側面も合わせて検討できるという複眼的視点",
